#include "cinderwatch/rules/rules.h"
namespace cinderwatch::rules{using namespace core;static std::vector<std::string> opts(const std::string&b){std::vector<std::string>o;std::string c;bool q=false;for(char x:b){if(x=='"'){q=!q;c.push_back(x);}else if(x==';'&&!q){auto t=trim(c);if(!t.empty())o.push_back(t);c.clear();}else c.push_back(x);}auto t=trim(c);if(!t.empty())o.push_back(t);return o;}Result<IdsRule> parse_ids(const std::string&l,size_t n){auto t=trim(l);auto lp=t.find('('),rp=t.rfind(')');if(lp==std::string::npos||rp==std::string::npos||rp<lp)return Status::error(Code::Malformed,"missing options");std::stringstream hs(t.substr(0,lp));IdsRule r;r.raw=l;r.line=n;if(!(hs>>r.action>>r.proto>>r.src_net>>r.src_port>>r.dir>>r.dst_net>>r.dst_port))return Status::error(Code::Malformed,"short header");r.action=lower(r.action);r.proto=lower(r.proto);size_t order=0;for(auto&o:opts(t.substr(lp+1,rp-lp-1))){auto p=o.find(':');IdsOption io;io.order=order++;if(p==std::string::npos){io.key=lower(trim(o));}else{io.key=lower(trim(o.substr(0,p)));io.value=trim(o.substr(p+1));io.quoted=io.value.size()>=2&&io.value.front()=='"'&&io.value.back()=='"';io.value=strip_quotes(io.value);}if(io.key=="sid")r.sid=std::atoi(io.value.c_str());else if(io.key=="rev")r.rev=std::atoi(io.value.c_str());else if(io.key=="priority")r.priority=std::atoi(io.value.c_str());else if(io.key=="msg")r.msg=io.value;else if(io.key=="classtype")r.classtype=io.value;r.options.push_back(io);}return r;}IdsSet parse_ids_rules(const std::string&t){IdsSet s;size_t n=0;for(auto&l:lines(t)){n++;auto x=trim(l);if(x.empty()||x[0]=='#')continue;auto r=parse_ids(x,n);if(r)s.rules.push_back(r.value());else s.diagnostics.push_back({Severity::Medium,"ids.parse",r.st.msg,{"",n,1,r.st.off}});}return s;}static bool any(const std::string&x){auto l=lower(x);return l=="any"||l=="*"||l=="0.0.0.0/0";}static bool has(const IdsRule&r,const std::string&k){for(auto&o:r.options)if(o.key==k)return true;return false;}Report validate_ids(const IdsSet&s){Report rep;rep.subject="IDS validation";rep.diagnostics=s.diagnostics;std::set<int>sid;for(auto&r:s.rules){if(r.sid<=0)rep.findings.push_back({Severity::High,"ids","Missing sid","Rule does not define a positive sid",{"",r.line,1,0},{r.raw}});else if(!sid.insert(r.sid).second)rep.findings.push_back({Severity::High,"ids","Duplicate sid","Rule sid duplicates another rule",{"",r.line,1,0},{r.raw}});if(r.rev<0)rep.findings.push_back({Severity::Medium,"ids","Missing rev","Rule does not define a revision",{"",r.line,1,0},{r.raw}});if(r.priority==0||r.priority>5)rep.findings.push_back({Severity::Medium,"ids","Invalid priority","Priority should be a small positive value",{"",r.line,1,0},{r.raw}});if(any(r.src_net)&&any(r.dst_net)&&any(r.src_port)&&any(r.dst_port)&&!has(r,"content"))rep.findings.push_back({Severity::High,"ids","Overly broad signature","Broad endpoints without content",{"",r.line,1,0},{r.raw}});int content=-1,depth=-1,offset=-1,distance=-1,within=-1;for(size_t i=0;i<r.options.size();++i){auto&o=r.options[i];if(o.key=="content"){content=int(i);if(o.value.empty())rep.findings.push_back({Severity::Medium,"ids","Malformed content","Content option is empty",{"",r.line,1,0},{r.raw}});}else if(o.key=="nocase"&&content<0)rep.findings.push_back({Severity::Low,"ids","Detached nocase","nocase appears before content",{"",r.line,1,0},{r.raw}});else if(o.key=="depth")depth=std::atoi(o.value.c_str());else if(o.key=="offset")offset=std::atoi(o.value.c_str());else if(o.key=="distance")distance=std::atoi(o.value.c_str());else if(o.key=="within")within=std::atoi(o.value.c_str());else if(o.key=="pcre"||o.key=="byte_test")rep.findings.push_back({Severity::Info,"ids","Unsupported option noted","Rule contains an option outside the inspected subset",{"",r.line,1,0},{o.key}});}if(depth>=0&&offset>=0&&depth<offset)rep.findings.push_back({Severity::Medium,"ids","Impossible content window","depth is smaller than offset",{"",r.line,1,0},{r.raw}});if(within>=0&&distance>=0&&within<distance)rep.findings.push_back({Severity::Medium,"ids","Impossible relative window","within is smaller than distance",{"",r.line,1,0},{r.raw}});}return rep;}std::string normalize_ids_rule(const IdsRule&r){auto os=r.options;std::stable_sort(os.begin(),os.end(),[](auto&a,auto&b){auto rank=[](const std::string&k){if(k=="msg")return 0;if(k=="flow")return 1;if(k=="content")return 2;if(k=="nocase")return 3;if(k=="sid")return 90;if(k=="rev")return 91;return 50;};int ra=rank(a.key),rb=rank(b.key);return ra==rb?a.order<b.order:ra<rb;});std::ostringstream o;o<<lower(r.action)<<' '<<lower(r.proto)<<' '<<r.src_net<<' '<<r.src_port<<' '<<r.dir<<' '<<r.dst_net<<' '<<r.dst_port<<" (";for(auto&x:os){o<<x.key;if(!x.value.empty()||x.quoted){o<<":";bool q=x.quoted||x.key=="msg"||x.key=="content";if(q)o<<'"';o<<x.value;if(q)o<<'"';}o<<"; ";}o<<")";return o.str();}std::string normalize_ids(const IdsSet&s){std::ostringstream o;for(auto&r:s.rules)o<<normalize_ids_rule(r)<<"\n";return o.str();}std::string ids_text(const IdsSet&s,const Report&r){std::ostringstream o;o<<"IDS rules parsed: "<<s.rules.size()<<"\n"<<report_text(r);return o.str();}std::string ids_json(const IdsSet&s,const Report&r){return std::string("{\"rules\":")+std::to_string(s.rules.size())+",\"report\":"+report_json(r)+"}";}}
